pub assume_specification<T>[ Bound::<T>::as_ref ](
    bound: &Bound<T>,
) -> (result: Bound<&T>)
    ensures
        spec_bound(result) == spec_bound_ref(bound),
;

pub assume_specification<B, C>[ ControlFlow::<B, C>::break_ok ](
    flow: ControlFlow<B, C>,
) -> (result: Result<B, C>)
    ensures
        result == match flow {
            ControlFlow::Continue(c) => Err(c),
            ControlFlow::Break(b) => Ok(b),
        },
;

pub assume_specification<B, C>[ ControlFlow::<B, C>::break_value ](
    flow: ControlFlow<B, C>,
) -> (result: Option<B>)
    ensures
        result == match flow {
            ControlFlow::Continue(_) => None,
            ControlFlow::Break(b) => Some(b),
        },
;

pub assume_specification<B, C>[ ControlFlow::<B, C>::continue_ok ](
    flow: ControlFlow<B, C>,
) -> (result: Result<C, B>)
    ensures
        result == match flow {
            ControlFlow::Continue(c) => Ok(c),
            ControlFlow::Break(b) => Err(b),
        },
;

pub assume_specification<B, C>[ ControlFlow::<B, C>::continue_value ](
    flow: ControlFlow<B, C>,
) -> (result: Option<C>)
    ensures
        result == match flow {
            ControlFlow::Continue(c) => Some(c),
            ControlFlow::Break(_) => None,
        },
;
